-- Durable partner selections. No personal-list lifecycle and no direct client
-- access to the private table. Existing public object serialization is reused.
-- Apply once through migration history. A direct replay intentionally fails
-- atomically instead of masking drift with IF NOT EXISTS or replacing data.
BEGIN;

CREATE TABLE internal.partner_selection (
  id bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1016) PRIMARY KEY,
  org_object_id text NOT NULL REFERENCES public.object(id) ON DELETE RESTRICT,
  name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 160),
  buckets jsonb NOT NULL,
  explorer_state jsonb,
  commune_insee text[],
  state text NOT NULL DEFAULT 'active' CHECK (state IN ('active', 'suspended')),
  revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX partner_selection_org_updated_idx
  ON internal.partner_selection(org_object_id, updated_at DESC, id);
-- Public identifiers are strings; preserve indexed lookups without casting
-- arbitrary client text to bigint (including overflow or malformed input).
CREATE INDEX partner_selection_public_id_idx ON internal.partner_selection ((id::text));
ALTER TABLE internal.partner_selection ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE internal.partner_selection FROM PUBLIC, anon, authenticated;
REVOKE ALL ON SEQUENCE internal.partner_selection_id_seq FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE internal.partner_selection TO service_role;
GRANT USAGE, SELECT ON SEQUENCE internal.partner_selection_id_seq TO service_role;

CREATE FUNCTION internal.partner_selection_can_manage(p_org_object_id text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public, api, internal, auth, pg_temp AS $$
  SELECT COALESCE((SELECT auth.uid()) IS NOT NULL AND (
    api.is_platform_superuser()
    OR (p_org_object_id = api.current_user_org_id()
      AND internal.org_is_admin((SELECT auth.uid()), p_org_object_id))
  ), false);
$$;

CREATE FUNCTION internal.partner_selection_validate(
  p_org_object_id text, p_name text, p_buckets jsonb,
  p_explorer_state jsonb, p_commune_insee text[]
) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public, api, internal, pg_temp AS $$
DECLARE b jsonb; f jsonb; k text; item jsonb; nested_key text; nested_value jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.object WHERE id = p_org_object_id AND object_type = 'ORG')
    OR COALESCE(length(btrim(p_name)), 0) NOT BETWEEN 1 AND 160
    OR jsonb_typeof(p_buckets) IS DISTINCT FROM 'array'
    OR (p_explorer_state IS NOT NULL AND jsonb_typeof(p_explorer_state) IS DISTINCT FROM 'object') THEN
    RAISE EXCEPTION 'invalid_selection_definition' USING ERRCODE = 'PT400';
  END IF;
  IF jsonb_array_length(p_buckets) NOT BETWEEN 1 AND 50
    OR octet_length(p_buckets::text) > 262144
    OR octet_length(COALESCE(p_explorer_state::text, '')) > 262144
    OR cardinality(p_commune_insee) > 100
    OR EXISTS (SELECT 1 FROM unnest(p_commune_insee) c WHERE c IS NULL OR c !~ '^[0-9]{5}$') THEN
    RAISE EXCEPTION 'invalid_selection_definition' USING ERRCODE = 'PT400';
  END IF;
  FOR b IN SELECT value FROM jsonb_array_elements(p_buckets) LOOP
    IF jsonb_typeof(b) IS DISTINCT FROM 'object'
      OR jsonb_typeof(b->'types') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'invalid_selection_bucket' USING ERRCODE = 'PT400';
    END IF;
    IF jsonb_array_length(b->'types') NOT BETWEEN 1 AND 19
      OR (b ? 'filters' AND jsonb_typeof(b->'filters') IS DISTINCT FROM 'object')
      OR (b ? 'search' AND jsonb_typeof(b->'search') NOT IN ('string', 'null'))
      OR (b ? 'only_without_practices' AND jsonb_typeof(b->'only_without_practices') IS DISTINCT FROM 'boolean')
      OR EXISTS (SELECT 1 FROM jsonb_object_keys(b) bucket_key WHERE bucket_key NOT IN ('types','filters','search','only_without_practices'))
      OR EXISTS (SELECT 1 FROM jsonb_array_elements(b->'types') t(code)
        WHERE jsonb_typeof(t.code) IS DISTINCT FROM 'string'
          OR NOT (t.code #>> '{}') = ANY(enum_range(NULL::public.object_type)::text[])) THEN
      RAISE EXCEPTION 'invalid_selection_bucket' USING ERRCODE = 'PT400';
    END IF;
    -- Only public Explorer criteria may become a published selection. Reject
    -- unknown keys rather than silently widening a misspelled filter, and
    -- reject editor-only completeness/publication predicates explicitly.
    f := COALESCE(b->'filters','{}'::jsonb);
    FOR k IN SELECT jsonb_object_keys(f) LOOP
      IF k NOT IN ('has_provider','search_mode','open_now','open_at','pet_accepted',
        'label_scheme_ranked','label_scheme_ranked_exact_only','classifications_any',
        'amenities_any','amenities_all','amenity_families_any','accessibility_any',
        'disability_types_any','label_disability_types_any','sustainability_any',
        'sustainability_categories_any','sustainability_actions_any','bbox',
        'city_any','lieu_dit_any','tags_any','environment_tags_any',
        'accommodation_unit_types_any','accommodation_positionings_any',
        'taxonomy_any','include_equivalent_predecessors','event','capacity_filters',
        'meeting_room','itinerary','payment_methods_any','languages_any','media_types_any',
        'cuisine_types_any') THEN
        RAISE EXCEPTION 'unsupported_public_selection_filter' USING ERRCODE='PT400';
      END IF;
      IF k IN ('has_provider','open_now','pet_accepted','label_scheme_ranked_exact_only',
        'accessibility_any','sustainability_any','include_equivalent_predecessors') THEN
        IF jsonb_typeof(f->k) IS DISTINCT FROM 'boolean' THEN
          RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
        END IF;
        IF k='open_now' AND f->k <> 'true'::jsonb THEN
          RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
        END IF;
      ELSIF k IN ('search_mode','label_scheme_ranked','open_at') THEN
        IF jsonb_typeof(f->k) IS DISTINCT FROM 'string' OR btrim(f->>k)='' THEN
          RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
        END IF;
        IF k='search_mode' AND f->>k NOT IN ('global','name') THEN
          RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
        END IF;
        IF k='open_at' THEN PERFORM (f->>k)::timestamptz; END IF;
      ELSIF k IN ('event','meeting_room','itinerary') THEN
        IF jsonb_typeof(f->k) IS DISTINCT FROM 'object' THEN
          RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
        END IF;
        IF EXISTS (SELECT 1 FROM jsonb_object_keys(f->k) nested WHERE
          (k='event' AND nested NOT IN ('from','to')) OR
          (k='meeting_room' AND nested NOT IN ('min_count','min_area_m2','min_cap_theatre','min_cap_classroom','equipment_any','equipment_all')) OR
          (k='itinerary' AND nested NOT IN ('is_loop','difficulty_min','difficulty_max','distance_min_km','distance_max_km','duration_min_h','duration_max_h','practices_any'))) THEN
          RAISE EXCEPTION 'unsupported_public_selection_filter' USING ERRCODE='PT400';
        END IF;
        FOR nested_key,nested_value IN SELECT key,value FROM jsonb_each(f->k) LOOP
          IF k='event' THEN
            IF jsonb_typeof(nested_value) IS DISTINCT FROM 'string' OR nested_value #>> '{}' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
            PERFORM (nested_value #>> '{}')::date;
          ELSIF nested_key IN ('practices_any','equipment_any','equipment_all') THEN
            IF jsonb_typeof(nested_value) IS DISTINCT FROM 'array' THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
            IF EXISTS (SELECT 1 FROM jsonb_array_elements(nested_value) v
              WHERE jsonb_typeof(v) IS DISTINCT FROM 'string' OR btrim(v #>> '{}')='') THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
          ELSIF nested_key='is_loop' THEN
            IF jsonb_typeof(nested_value) IS DISTINCT FROM 'boolean' THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
          ELSE
            IF jsonb_typeof(nested_value) IS DISTINCT FROM 'number' THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
            IF (nested_value #>> '{}')::numeric < 0
              OR (nested_key IN ('difficulty_min','difficulty_max','min_count','min_cap_theatre','min_cap_classroom')
                AND ((nested_value #>> '{}')::numeric > 2147483647
                  OR (nested_value #>> '{}')::numeric <> trunc((nested_value #>> '{}')::numeric))) THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
          END IF;
        END LOOP;
      ELSE
        IF jsonb_typeof(f->k) IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
        END IF;
        IF k='bbox' AND jsonb_array_length(f->k)<>4 THEN
          RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
        END IF;
        IF k='cuisine_types_any' AND (jsonb_array_length(f->k)>100
          OR (jsonb_array_length(f->k)>0 AND (jsonb_array_length(b->'types')<>1 OR b->'types'->>0<>'RES'))) THEN
          RAISE EXCEPTION 'invalid_cuisine_types' USING ERRCODE='PT400';
        END IF;
        FOR item IN SELECT value FROM jsonb_array_elements(f->k) LOOP
          IF k IN ('taxonomy_any','classifications_any','capacity_filters')
            AND jsonb_typeof(item) IS DISTINCT FROM 'object' THEN
            RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
          END IF;
          IF k='taxonomy_any' THEN
            IF jsonb_typeof(item) IS DISTINCT FROM 'object'
              OR jsonb_typeof(item->'domain') IS DISTINCT FROM 'string'
              OR jsonb_typeof(item->'code') IS DISTINCT FROM 'string'
              OR item->>'domain' !~ '^taxonomy_[a-z_]+$' OR btrim(item->>'code')=''
              OR EXISTS (SELECT 1 FROM jsonb_object_keys(item) nested WHERE nested NOT IN ('domain','code')) THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
          ELSIF k='classifications_any' THEN
            IF jsonb_typeof(item) IS DISTINCT FROM 'object'
              OR COALESCE(item->>'scheme_code','')='' OR COALESCE(item->>'value_code','')=''
              OR EXISTS (SELECT 1 FROM jsonb_object_keys(item) nested WHERE nested NOT IN ('scheme_code','value_code')) THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
          ELSIF k='bbox' THEN
            IF jsonb_typeof(item) IS DISTINCT FROM 'number' OR jsonb_array_length(f->k)<>4 THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
          ELSIF k='capacity_filters' THEN
            IF jsonb_typeof(item) IS DISTINCT FROM 'object'
              OR jsonb_typeof(item->'code') IS DISTINCT FROM 'string' OR btrim(item->>'code')=''
              OR NOT (item ? 'min' OR item ? 'max')
              OR (item ? 'min' AND (jsonb_typeof(item->'min') IS DISTINCT FROM 'number'))
              OR (item ? 'max' AND (jsonb_typeof(item->'max') IS DISTINCT FROM 'number'))
              OR EXISTS (SELECT 1 FROM jsonb_object_keys(item) nested WHERE nested NOT IN ('code','min','max')) THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
            IF (item ? 'min' AND ((item->>'min')::numeric < 0 OR (item->>'min')::numeric <> trunc((item->>'min')::numeric)))
              OR (item ? 'max' AND ((item->>'max')::numeric < 0 OR (item->>'max')::numeric <> trunc((item->>'max')::numeric)))
              OR (item ? 'min' AND (item->>'min')::numeric > 2147483647)
              OR (item ? 'max' AND (item->>'max')::numeric > 2147483647)
              OR (item ? 'min' AND item ? 'max' AND (item->>'min')::numeric > (item->>'max')::numeric) THEN
              RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
            END IF;
          ELSIF jsonb_typeof(item) IS DISTINCT FROM 'string' OR btrim(item #>> '{}')='' THEN
            RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
          END IF;
          IF k='cuisine_types_any' AND NOT EXISTS (SELECT 1 FROM public.ref_code_cuisine_type r
            WHERE r.code=(item #>> '{}') AND r.is_active) THEN
            RAISE EXCEPTION 'unknown_cuisine_type' USING ERRCODE='PT400';
          END IF;
        END LOOP;
      END IF;
    END LOOP;
  END LOOP;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
  RAISE EXCEPTION 'invalid_public_selection_filter' USING ERRCODE='PT400';
END;
$$;

CREATE FUNCTION internal.partner_selection_document(p_row internal.partner_selection)
RETURNS jsonb LANGUAGE sql STABLE
SET search_path = pg_catalog, internal, pg_temp AS $$
  SELECT jsonb_build_object('id', p_row.id::text, 'org_object_id', p_row.org_object_id,
    'name', p_row.name, 'buckets', p_row.buckets, 'explorer_state', p_row.explorer_state,
    'commune_insee', p_row.commune_insee, 'state', p_row.state, 'revision', p_row.revision,
    'created_by', p_row.created_by, 'updated_by', p_row.updated_by,
    'created_at', p_row.created_at, 'updated_at', p_row.updated_at);
$$;

REVOKE ALL ON FUNCTION internal.partner_selection_can_manage(text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION internal.partner_selection_validate(text,text,jsonb,jsonb,text[]) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION internal.partner_selection_document(internal.partner_selection) FROM PUBLIC, anon, authenticated;

CREATE FUNCTION api.list_partner_selections(p_org_object_id text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public, api, internal, auth, pg_temp AS $$
DECLARE org_id text := COALESCE(p_org_object_id, api.current_user_org_id());
BEGIN
  IF NOT internal.partner_selection_can_manage(org_id) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  RETURN (SELECT COALESCE(jsonb_agg(internal.partner_selection_document(s)
    ORDER BY s.updated_at DESC, s.id), '[]'::jsonb)
    FROM internal.partner_selection s WHERE s.org_object_id = org_id);
END;
$$;

CREATE FUNCTION api.get_partner_selection(p_selection_id text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public, api, internal, auth, pg_temp AS $$
DECLARE s internal.partner_selection;
BEGIN
  SELECT * INTO s FROM internal.partner_selection WHERE id::text = p_selection_id;
  IF s.id IS NULL OR NOT internal.partner_selection_can_manage(s.org_object_id) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  RETURN internal.partner_selection_document(s);
END;
$$;

CREATE FUNCTION api.create_partner_selection(
  p_name text, p_buckets jsonb, p_org_object_id text DEFAULT NULL,
  p_explorer_state jsonb DEFAULT NULL, p_commune_insee text[] DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public, api, internal, auth, pg_temp AS $$
DECLARE org_id text := COALESCE(p_org_object_id, api.current_user_org_id()); s internal.partner_selection;
BEGIN
  IF NOT internal.partner_selection_can_manage(org_id) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  PERFORM internal.partner_selection_validate(org_id,p_name,p_buckets,p_explorer_state,p_commune_insee);
  INSERT INTO internal.partner_selection(org_object_id,name,buckets,explorer_state,commune_insee,created_by,updated_by)
  VALUES(org_id,btrim(p_name),p_buckets,p_explorer_state,p_commune_insee,(SELECT auth.uid()),(SELECT auth.uid()))
  RETURNING * INTO s;
  RETURN internal.partner_selection_document(s);
END;
$$;

CREATE FUNCTION api.update_partner_selection(
  p_selection_id text, p_expected_revision integer, p_name text, p_buckets jsonb,
  p_explorer_state jsonb DEFAULT NULL, p_commune_insee text[] DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public, api, internal, auth, pg_temp AS $$
DECLARE s internal.partner_selection;
BEGIN
  SELECT * INTO s FROM internal.partner_selection WHERE id::text=p_selection_id FOR UPDATE;
  IF s.id IS NULL OR NOT internal.partner_selection_can_manage(s.org_object_id) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF p_expected_revision IS DISTINCT FROM s.revision THEN
    RAISE EXCEPTION 'selection_revision_conflict' USING ERRCODE = 'PT409';
  END IF;
  PERFORM internal.partner_selection_validate(s.org_object_id,p_name,p_buckets,p_explorer_state,p_commune_insee);
  UPDATE internal.partner_selection SET name=btrim(p_name), buckets=p_buckets,
    explorer_state=p_explorer_state, commune_insee=p_commune_insee,
    revision=revision+1, updated_by=(SELECT auth.uid()), updated_at=clock_timestamp()
  WHERE id=s.id RETURNING * INTO s;
  RETURN internal.partner_selection_document(s);
END;
$$;

CREATE FUNCTION api.set_partner_selection_state(p_selection_id text,p_expected_revision integer,p_state text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public, api, internal, auth, pg_temp AS $$
DECLARE s internal.partner_selection;
BEGIN
  SELECT * INTO s FROM internal.partner_selection WHERE id::text=p_selection_id FOR UPDATE;
  IF s.id IS NULL OR NOT internal.partner_selection_can_manage(s.org_object_id) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF p_expected_revision IS DISTINCT FROM s.revision THEN
    RAISE EXCEPTION 'selection_revision_conflict' USING ERRCODE = 'PT409';
  END IF;
  IF p_state IS NULL OR p_state NOT IN ('active','suspended') THEN
    RAISE EXCEPTION 'invalid_selection_state' USING ERRCODE = 'PT400';
  END IF;
  IF s.state IS DISTINCT FROM p_state THEN
    UPDATE internal.partner_selection SET state=p_state, revision=revision+1,
      updated_by=(SELECT auth.uid()), updated_at=clock_timestamp()
    WHERE id=s.id RETURNING * INTO s;
  END IF;
  RETURN internal.partner_selection_document(s);
END;
$$;

-- Validate an unsaved draft with the human caller's current organization rights.
-- A Next server route may then resolve this definition through the existing
-- service-role public reader, ensuring identical publication/test-realm rules.
CREATE FUNCTION api.prepare_partner_selection_preview(
  p_buckets jsonb, p_org_object_id text DEFAULT NULL,
  p_commune_insee text[] DEFAULT NULL, p_name text DEFAULT 'Aperçu'
) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public, api, internal, auth, pg_temp AS $$
DECLARE org_id text := COALESCE(p_org_object_id, api.current_user_org_id());
BEGIN
  IF NOT internal.partner_selection_can_manage(org_id) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  PERFORM internal.partner_selection_validate(org_id,p_name,p_buckets,NULL,p_commune_insee);
  RETURN jsonb_build_object('id','preview','org_object_id',org_id,'name',btrim(p_name),
    'revision',1,'buckets',p_buckets,'commune_insee',p_commune_insee);
END;
$$;

CREATE FUNCTION api.get_active_partner_selection_definition(p_selection_id text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER
SET search_path = pg_catalog, internal, pg_temp AS $$
DECLARE s internal.partner_selection;
BEGIN
  SELECT * INTO s FROM internal.partner_selection WHERE id::text=p_selection_id AND state='active';
  IF s.id IS NULL THEN RETURN NULL; END IF;
  PERFORM internal.partner_selection_validate(s.org_object_id,s.name,s.buckets,s.explorer_state,s.commune_insee);
  RETURN internal.partner_selection_document(s);
END;
$$;

REVOKE ALL ON FUNCTION api.list_partner_selections(text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION api.get_partner_selection(text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION api.create_partner_selection(text,jsonb,text,jsonb,text[]) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION api.update_partner_selection(text,integer,text,jsonb,jsonb,text[]) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION api.set_partner_selection_state(text,integer,text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION api.prepare_partner_selection_preview(jsonb,text,text[],text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION api.list_partner_selections(text), api.get_partner_selection(text),
  api.create_partner_selection(text,jsonb,text,jsonb,text[]),
  api.update_partner_selection(text,integer,text,jsonb,jsonb,text[]),
  api.set_partner_selection_state(text,integer,text),
  api.prepare_partner_selection_preview(jsonb,text,text[],text) TO authenticated;
REVOKE ALL ON FUNCTION api.get_active_partner_selection_definition(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION api.get_active_partner_selection_definition(text) TO service_role;
GRANT EXECUTE ON FUNCTION internal.partner_selection_document(internal.partner_selection) TO service_role;

-- Explicit, service-only import: never overwrites a managed selection. The
-- verified OTI deployment below is conditional so fresh databases stay generic.
CREATE FUNCTION api.seed_beta_partner_selections(p_org_object_id text)
RETURNS integer LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, public, api, internal, pg_temp AS $$
DECLARE definitions jsonb := $beta$[{"id":"1001","name":"À pied","revision":1,"buckets":[{"types":["ITI"],"filters":{"itinerary":{"practices_any":["randonnee_pedestre"]}}},{"types":["ITI"],"filters":{"taxonomy_any":[{"domain":"taxonomy_iti","code":"hiking"},{"domain":"taxonomy_iti","code":"interpretive_trail"},{"domain":"taxonomy_iti","code":"coastal_path"}]},"only_without_practices":true}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1002","name":"À vélo","revision":1,"buckets":[{"types":["ITI"],"filters":{"itinerary":{"practices_any":["velo_route","velo_vtt","cyclotourisme"]}}},{"types":["ITI"],"filters":{"taxonomy_any":[{"domain":"taxonomy_iti","code":"mountain_biking"}]},"only_without_practices":true}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1003","name":"Nature","revision":1,"buckets":[{"types":["PNA"]}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1004","name":"Patrimoine","revision":1,"buckets":[{"types":["PCU"]}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1005","name":"Loisirs","revision":1,"buckets":[{"types":["ACT","ASC","LOI"]}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1006","name":"Terroir et artisanat","revision":1,"buckets":[{"types":["PRD"]},{"types":["COM"],"filters":{"taxonomy_any":[{"domain":"taxonomy_com","code":"local_crafts"},{"domain":"taxonomy_com","code":"weekly_market"},{"domain":"taxonomy_com","code":"covered_market"}]}}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1007","name":"Événements","revision":1,"buckets":[{"types":["FMA"]}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1008","name":"Restaurants","revision":1,"buckets":[{"types":["RES"]}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1009","name":"Hôtels","revision":1,"buckets":[{"types":["HOT"]}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1010","name":"Locations et chambres","revision":1,"buckets":[{"types":["HLO"]}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1011","name":"Campings et aires","revision":1,"buckets":[{"types":["CAMP","HPA"]}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1012","name":"Résidences","revision":1,"buckets":[{"types":["RVA"]}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1013","name":"Transports","revision":1,"buckets":[{"types":["PSV"],"filters":{"taxonomy_any":[{"domain":"taxonomy_psv","code":"transport_mobility"},{"domain":"taxonomy_psv","code":"autocar_compagnie"},{"domain":"taxonomy_psv","code":"location_vehicule"},{"domain":"taxonomy_psv","code":"cycle_scooter_rental"}]}},{"types":["SPU"],"filters":{"taxonomy_any":[{"domain":"taxonomy_spu","code":"bus_station"},{"domain":"taxonomy_spu","code":"carpool_area"},{"domain":"taxonomy_spu","code":"tourist_parking"}]}}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1014","name":"Offices de tourisme","revision":1,"buckets":[{"types":["SPU"],"filters":{"taxonomy_any":[{"domain":"taxonomy_spu","code":"tourist_info_office"}]}}],"communeInsee":["97403","97412","97417","97422"]},{"id":"1015","name":"Services","revision":1,"buckets":[{"types":["SPU"],"filters":{"taxonomy_any":[{"domain":"taxonomy_spu","code":"public_toilets"},{"domain":"taxonomy_spu","code":"drinking_water"},{"domain":"taxonomy_spu","code":"picnic_area"},{"domain":"taxonomy_spu","code":"electric_charging"},{"domain":"taxonomy_spu","code":"motorhome_services"}]}}],"communeInsee":["97403","97412","97417","97422"]}]$beta$; d jsonb; existing internal.partner_selection; inserted integer := 0;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.object WHERE id=p_org_object_id
    AND object_type='ORG' AND is_test IS FALSE) THEN
    RAISE EXCEPTION 'invalid_selection_owner' USING ERRCODE='PT400';
  END IF;
  FOR d IN SELECT value FROM jsonb_array_elements(definitions) LOOP
    SELECT * INTO existing FROM internal.partner_selection WHERE id=(d->>'id')::bigint FOR UPDATE;
    IF existing.id IS NOT NULL THEN
      IF existing.org_object_id IS DISTINCT FROM p_org_object_id THEN
        RAISE EXCEPTION 'beta_selection_owner_conflict' USING ERRCODE='PT409';
      END IF;
      CONTINUE;
    END IF;
    PERFORM internal.partner_selection_validate(p_org_object_id,d->>'name',d->'buckets',NULL,
      ARRAY(SELECT jsonb_array_elements_text(d->'communeInsee')));
    INSERT INTO internal.partner_selection(id,org_object_id,name,buckets,commune_insee)
    VALUES((d->>'id')::bigint,p_org_object_id,d->>'name',d->'buckets',
      ARRAY(SELECT jsonb_array_elements_text(d->'communeInsee')));
    inserted := inserted+1;
  END LOOP;
  RETURN inserted;
END;
$$;
REVOKE ALL ON FUNCTION api.seed_beta_partner_selections(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION api.seed_beta_partner_selections(text) TO service_role;
GRANT EXECUTE ON FUNCTION internal.partner_selection_validate(text,text,jsonb,jsonb,text[]) TO service_role;

DO $seed_verified_oti$
BEGIN
  IF EXISTS (SELECT 1 FROM public.object WHERE id='ORGRUN000000000B'
    AND object_type='ORG' AND name='OTI du Sud' AND is_test IS FALSE) THEN
    PERFORM api.seed_beta_partner_selections('ORGRUN000000000B');
  END IF;
END;
$seed_verified_oti$;
COMMENT ON TABLE internal.partner_selection IS 'Durable organization-owned dynamic public selections. Private CRUD via role-gated RPC; partner reader service-only.';
NOTIFY pgrst, 'reload schema';
COMMIT;
